// ---------------- 60s Morning Audio Brief (Web Speech API + Visual Teleprompter) ----------------
window.toggleVoiceBrief = function() {
  const btn1 = $("#btn-voice-brief");
  const btn2 = $("#hdr-audio-btn");
  if (STATE.speaking) {
    try { window.speechSynthesis.cancel(); } catch (e) {}
    STATE.speaking = false;
    if (btn1) btn1.textContent = "🔊 60s Audio Brief";
    if (btn2) btn2.classList.remove("playing");
    showToast("Audio brief stopped");
    return;
  }
  const actItems = getFilteredDigestItems().filter((i) => i.tier === "act").slice(0, 4);
  const script = `Good morning. Here is your 60-second FINN intelligence brief across ${STATE.portfolio.length} portfolio holdings. ` +
    `${actItems.length} material filings require your attention today. ` +
    actItems.map((it, idx) => `${idx + 1}: ${it.name}, ${catLabel(it.category)}. ${it.subject}. ${it.summary || ""} Stock moved ${it.price.change_pct >= 0 ? "up" : "down"} ${Math.abs(it.price.change_pct)} percent.`).join(" ") +
    ` On Radar, Dixon Technologies is up 6.2 percent on 3.1 times volume following its display module joint venture filing, while Deepak Nitrite is down 5.4 percent on 2.4 times volume.`;

  if ("speechSynthesis" in window) {
    try {
      window.speechSynthesis.cancel();
      const u = new SpeechSynthesisUtterance(script);
      u.rate = 1.04;
      u.onend = () => {
        STATE.speaking = false;
        if (btn1) btn1.textContent = "🔊 60s Audio Brief";
        if (btn2) btn2.classList.remove("playing");
      };
      STATE.speaking = true;
      if (btn1) btn1.textContent = "⏹ Stop Audio Brief";
      if (btn2) btn2.classList.add("playing");
      window.speechSynthesis.speak(u);
      showToast("🔊 Playing 60s Morning Audio Brief…");
      return;
    } catch (e) {}
  }
  // Visual fallback modal if browser blocks speechSynthesis
  $("#fm-title").textContent = "🔊 60-Second Morning Audio Brief (Transcript)";
  $("#fm-body").innerHTML = `<div style="font-size:13.5px;line-height:1.6;color:var(--ink-soft);padding:6px 0">${esc(script)}</div>`;
  openModal("filing-modal");
};

// ---------------- TAB 1: BRIEF (PUSH DIGEST) ----------------
function computePriorityForItem(it) {
  const care = new Set(STATE.settings.care_categories || []);
  let p = SEED.category_priority[it.category] || 5;
  const reasons = [];
  if (care.has(it.category)) { p += 10; reasons.push("type you track"); }
  if (/intimation|notice of|newspaper|publication/i.test(it.subject)) { p -= 25; reasons.push("procedural notice"); }
  if (["press_release", "capex", "M&A"].includes(it.category) && /significant|large|major|crore/i.test(it.text || "")) {
    p += 8; reasons.push("sizeable deal/spend");
  }
  if (it.price && (Math.abs(it.price.change_pct) >= 3 || it.price.volume_multiple >= 2)) {
    p += 10;
    reasons.push(`stock moved ${it.price.change_pct >= 0 ? "+" : ""}${it.price.change_pct.toFixed(1)}% on ${it.price.volume_multiple}× vol`);
  }
  p = Math.max(0, Math.min(100, p));
  const tier = p >= 75 ? "act" : p >= 40 ? "watch" : "routine";
  return { priority: p, tier, why: reasons };
}

function getFilteredDigestItems() {
  const nowSec = Math.max(...SEED.digest_items_720h.map((x) => x.ts)) + 900;
  const cutoff = nowSec - STATE.hours * 3600;
  const portSyms = new Set(STATE.portfolio.map((p) => p.symbol));
  return SEED.digest_items_720h
    .filter((it) => portSyms.has(it.symbol) && it.ts >= cutoff)
    .map((it) => {
      const scored = computePriorityForItem(it);
      return { ...it, ...scored };
    })
    .sort((a, b) => b.priority - a.priority || b.ts - a.ts);
}

