function renderBrief() {
  const allWindowItems = getFilteredDigestItems();
  const actAll = allWindowItems.filter((i) => i.tier === "act");
  const seenActCount = actAll.filter((i) => STATE.seen.has(idOf(i))).length;
  const unseenActCount = actAll.length - seenActCount;
  const pct = actAll.length ? Math.round((seenActCount / actAll.length) * 100) : 100;

  $("#triage-status-lbl").textContent = actAll.length
    ? `${seenActCount} of ${actAll.length} Act-On filings triaged`
    : "All clear — zero Act-On filings";
  $("#triage-pct-lbl").textContent = `${pct}%`;
  $("#triage-fill-bar").style.width = `${pct}%`;
  setBadge("#b-brief", unseenActCount);

  // Apply category & unseen filter
  let items = allWindowItems;
  if (STATE.unseenOnly) items = items.filter((i) => !STATE.seen.has(idOf(i)));
  if (STATE.briefCat === "capex") items = items.filter((i) => ["capex", "press_release"].includes(i.category));
  else if (STATE.briefCat === "risk") items = items.filter((i) => ["litigation", "pledging", "insider_trading"].includes(i.category));
  else if (STATE.briefCat === "bookmarked") items = items.filter((i) => STATE.bookmarks.has(idOf(i)));
  else if (STATE.briefCat !== "all") items = items.filter((i) => i.category === STATE.briefCat);

  const act = items.filter((i) => i.tier === "act");
  const watch = items.filter((i) => i.tier === "watch");
  const routine = items.filter((i) => i.tier === "routine");

  const winLabel = STATE.hours < 48 ? `${STATE.hours}h` : `${STATE.hours / 24}d`;
  $("#brief-headline").innerHTML = allWindowItems.length
    ? `<b>${unseenActCount}</b> material filing${unseenActCount === 1 ? "" : "s"} need you. ${watch.length} on watch.`
    : "Quiet window across your portfolio.";
  $("#brief-sub").textContent = `${allWindowItems.length} disclosures across ${STATE.portfolio.length} NSE holdings in last ${winLabel} · ${routine.length} routine compliance items buried`;

  const groupHtml = (title, list) => !list.length ? "" :
    `<div class="group-h"><span>${title}</span><span class="n">${list.length}</span></div>${list.map(renderItemCard).join("")}`;

  const routineHtml = routine.length ? `
    <div class="group-h"><span>Routine & Procedural (Buried)</span><span class="n">${routine.length}</span></div>
    <details class="card routine">
      <summary><span>${routine.length} low-signal filings collapsed (ESOPs, Reg 74(5), notices)</span><span style="color:var(--accent);font-size:12px">Tap to expand ▾</span></summary>
      ${routine.map((i) => `<div class="rline">
        <b style="color:var(--ink);min-width:76px;cursor:pointer" onclick="jumpToResearch('${esc(i.symbol)}')">${esc(i.symbol)}</b>
        <span class="tag">${esc(catLabel(i.category))}</span>
        <span style="flex:1">${esc(i.subject)}</span>
        <a href="${esc(i.url)}" target="_blank" rel="noopener">↗</a>
      </div>`).join("")}
    </details>` : "";

  $("#brief-list").innerHTML = (groupHtml("Act On · High Conviction", act) + groupHtml("Watch · Worth a Glance", watch) + routineHtml)
    || `<div class="card" style="text-align:center;color:var(--mute);padding:26px">No filings match the current filter in the last ${winLabel}.</div>`;
}

