function sparkSvg(pts, cls) {
  if (!pts || !pts.length) return "";
  const mn = Math.min(...pts), mx = Math.max(...pts), w = 120, h = 32;
  const coords = pts.map((p, i) => [
    (i / (pts.length - 1)) * (w - 6) + 3,
    h - ((p - mn) / (mx - mn || 1)) * (h - 8) - 4
  ]);
  const d = coords.map((c) => `${c[0].toFixed(1)},${c[1].toFixed(1)}`).join(" ");
  const last = coords[coords.length - 1];
  const color = cls === "up" ? "var(--up)" : "var(--down)";
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">
    <polyline fill="none" stroke="${color}" stroke-width="1.75" points="${d}"/>
    <circle cx="${last[0].toFixed(1)}" cy="${last[1].toFixed(1)}" r="2.8" fill="${color}"/>
  </svg>`;
}

