function renderRadar() {
  const s = STATE.settings;
  $("#s-vol").value = s.volume_multiple;
  $("#s-px").value = s.price_move_pct;
  $("#v-vol").textContent = `> ${(+s.volume_multiple).toFixed(1)}× avg`;
  $("#v-px").textContent = `beyond ±${(+s.price_move_pct).toFixed(1)}%`;

  const care = new Set(s.care_categories || []);
  $("#s-cats").innerHTML = ALL_CATS.map((c) =>
    `<button type="button" class="chip cat-chip ${care.has(c) ? "on" : ""}" onclick="toggleCareCategory('${c}')">${esc(catLabel(c))}</button>`
  ).join("");

  // Ensure every portfolio stock has a watch tile
  const portTiles = STATE.portfolio.map((p) => getOrGenerateWatchTile(p.symbol, p.name, p.sector));
  const digest48 = getFilteredDigestItems();
  const filingsBySym = {};
  digest48.forEach((it) => {
    if (it.tier !== "routine") (filingsBySym[it.symbol] = filingsBySym[it.symbol] || []).push(it);
  });

  const marketAlerts = [];
  portTiles.forEach((st) => {
    const reasons = [];
    if (st.volume_multiple >= s.volume_multiple) reasons.push(`Volume ${st.volume_multiple}× its 20-day average`);
    if (Math.abs(st.change_pct) >= s.price_move_pct) reasons.push(`Price ${st.change_pct >= 0 ? "+" : ""}${st.change_pct}% (threshold ±${s.price_move_pct}%)`);
    if (reasons.length) {
      const cause = (filingsBySym[st.symbol] || [])[0];
      marketAlerts.push({
        kind: "market",
        symbol: st.symbol,
        name: st.name,
        sector: st.sector,
        reasons,
        stats: st,
        cause,
        severity: st.volume_multiple / s.volume_multiple + Math.abs(st.change_pct) / s.price_move_pct
      });
    }
  });

  const movedSyms = new Set(marketAlerts.map((a) => a.symbol));
  const filingAlerts = digest48
    .filter((it) => care.has(it.category) && it.tier === "act" && !movedSyms.has(it.symbol))
    .map((it) => ({
      kind: "filing",
      symbol: it.symbol,
      name: it.name,
      sector: it.sector,
      item: it,
      severity: it.priority / 50
    }));

  const allAlerts = [...marketAlerts, ...filingAlerts].sort((a, b) => b.severity - a.severity);
  $("#radar-headline").innerHTML = `<b>${allAlerts.length}</b> active trigger${allAlerts.length === 1 ? "" : "s"} · ${marketAlerts.length} EOD anomaly move${marketAlerts.length === 1 ? "" : "s"}, ${filingAlerts.length} material filing${filingAlerts.length === 1 ? "" : "s"}`;
  setBadge("#b-radar", marketAlerts.length);

  $("#alert-list").innerHTML = allAlerts.map((a) => {
    if (a.kind === "market") {
      return `<div class="card act">
        <div class="row">
          <span class="sym" onclick="jumpToResearch('${esc(a.symbol)}')">${esc(a.symbol)}</span>
          <span class="co">${esc(a.name)}</span>
          <span class="sec-badge">${esc(a.sector || "NSE")}</span>
          <span class="sp"></span>
          <span class="tag" style="color:var(--amber);background:var(--amber-bg)">⚡ EOD Anomaly</span>
        </div>
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:8px">
          <div>
            <div style="font-size:16px;font-weight:700">
              <span class="num ${a.stats.change_pct >= 0 ? "up" : "down"}">${a.stats.change_pct >= 0 ? "+" : ""}${a.stats.change_pct}%</span>
              on <span class="num" style="color:var(--ink)">${a.stats.volume_multiple}×</span> 20d avg volume
            </div>
            <div style="font-size:12px;color:var(--mute);margin-top:2px">${a.reasons.map(esc).join(" · ")} · Close ₹${fmtNum(a.stats.close)}</div>
          </div>
          <div style="width:110px">${sparkSvg(a.stats.spark, a.stats.change_pct >= 0 ? "up" : "down")}</div>
        </div>
        ${a.cause
          ? `<div class="cause-box">🔗 <b>Joined Filing Catalyst (${esc(catLabel(a.cause.category))}):</b> ${esc(a.cause.subject)}</div>`
          : `<div class="cause-box unexplained">⚠️ <b>Unexplained by Exchange Filings:</b> No NSE/BSE disclosure in last 48h — check institutional block deals or sector read-across.</div>`
        }
        <div class="meta">
          <span>20d Avg Vol: ${(a.stats.avg_volume / 1e5).toFixed(1)}L shares</span>
          <div class="card-actions">
            ${a.cause ? `<button type="button" class="act-link" onclick="inspectFilingModal('${esc(idOf(a.cause))}', event)">View Filing</button>` : ""}
            <button type="button" class="act-link pri" onclick="jumpToResearch('${esc(a.symbol)}')">Analyse ${esc(a.symbol)} →</button>
          </div>
        </div>
      </div>`;
    } else {
      const it = a.item;
      return `<div class="card watch">
        <div class="row">
          <span class="sym" onclick="jumpToResearch('${esc(a.symbol)}')">${esc(a.symbol)}</span>
          <span class="co">${esc(a.name)}</span>
          <span class="sp"></span>
          <span class="tag t-${it.category}">${esc(catLabel(it.category))}</span>
        </div>
        <div class="subj">${esc(it.subject)}</div>
        ${it.summary ? `<div class="summ">${esc(it.summary)}</div>` : ""}
        <div class="meta">
          <span class="why-pill">Material category trigger</span>
          <span>${ago(it.ts)} ago</span>
          <div class="card-actions">
            <button type="button" class="act-link" onclick="inspectFilingModal('${esc(idOf(it))}', event)">Excerpt</button>
            <button type="button" class="act-link pri" onclick="jumpToResearch('${esc(a.symbol)}')">Research →</button>
          </div>
        </div>
      </div>`;
    }
  }).join("") || `<div class="card" style="text-align:center;color:var(--mute);padding:24px">Nothing crossed your configured thresholds today. Lower the sliders above to test sensitivity.</div>`;

  // Render Watchlist Grid
  $("#port-count-lbl").textContent = portTiles.length;
  const sortedTiles = [...portTiles].sort((a, b) =>
    STATE.watchlistSort === "vol" ? b.volume_multiple - a.volume_multiple : Math.abs(b.change_pct) - Math.abs(a.change_pct)
  );
  $("#watchlist").innerHTML = sortedTiles.map((w) => {
    const hot = w.volume_multiple >= s.volume_multiple || Math.abs(w.change_pct) >= s.price_move_pct;
    return `<div class="tile ${hot ? "hot" : ""}" onclick="jumpToResearch('${esc(w.symbol)}')">
      <div class="row">
        <span class="sym">${esc(w.symbol)}</span>
        <span class="sp"></span>
        <span class="chg ${w.change_pct >= 0 ? "up" : "down"}">${w.change_pct >= 0 ? "+" : ""}${w.change_pct}%</span>
      </div>
      <div style="font-size:11px;color:var(--mute);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(w.name)}</div>
      ${sparkSvg(w.spark, w.change_pct >= 0 ? "up" : "down")}
      <div class="row vm">
        <span class="num" style="color:var(--ink-soft)">₹${fmtNum(w.close)}</span>
        <span class="sp"></span>
        <span class="num" style="${w.volume_multiple >= s.volume_multiple ? "color:var(--amber);font-weight:700" : ""}">Vol ${w.volume_multiple}×</span>
      </div>
    </div>`;
  }).join("");
}

