function renderTrajectoryChart(t) {
  const n = t.sales.length;
  if (!n) return "";
  const W = 360, H = 135, pad = 24, bw = ((W - pad) / n) * 0.56;
  const mx = Math.max(...t.sales.filter((x) => x != null)) || 1;
  const opm = t.opm.filter((x) => x != null);
  const omn = Math.min(...opm) - 2, omx = Math.max(...opm) + 2;
  const x = (i) => pad / 2 + (i + 0.5) * ((W - pad) / n);

  const bars = t.sales.map((s, i) => {
    const h = (s / mx) * (H - 34);
    const ph = ((t.pat[i] || 0) / mx) * (H - 34);
    return `<rect x="${(x(i) - bw / 2).toFixed(1)}" y="${(H - 18 - h).toFixed(1)}" width="${bw.toFixed(1)}" height="${h.toFixed(1)}" rx="3" fill="#26334d"/>
      <rect x="${(x(i) - bw / 2).toFixed(1)}" y="${(H - 18 - ph).toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(ph, 2).toFixed(1)}" rx="3" fill="var(--accent)"/>
      <text x="${x(i).toFixed(1)}" y="${H - 4}" fill="var(--mute)" font-size="8.5" text-anchor="middle">${esc((t.years[i] || "").slice(-2))}</text>`;
  }).join("");

  const pts = t.opm.map((o, i) => o == null ? null : `${x(i).toFixed(1)},${(10 + (1 - (o - omn) / (omx - omn || 1)) * (H - 44)).toFixed(1)}`).filter(Boolean).join(" ");
  return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}">${bars}<polyline fill="none" stroke="var(--amber)" stroke-width="2" points="${pts}"/></svg>
    <div class="legend">
      <span><i style="background:#26334d"></i>Revenue (₹ Cr)</span>
      <span><i style="background:var(--accent)"></i>Net Profit / PAT (₹ Cr)</span>
      <span><i style="background:var(--amber)"></i>Operating Margin % (${t.opm[0]}% → ${t.opm[t.opm.length - 1]}%)</span>
    </div>`;
}

function synthesizeGroundedAnswer(r, question) {
  const q = question.toLowerCase();
  const sym = r.symbol;
  const L = r.latest;
  const t = r.trajectory;
  const pvd = r.promise_vs_delivered;
  const c = r.cash;
  const b = r.balance;

  if (/promise|deliver|guid|credib|narrativ|walk|talk|call/.test(q)) {
    const rowsTxt = pvd.rows.map((x) => `• ${x.period} (${x.metric}): Promised ${x.low}–${x.high}%, Delivered ${x.delivered}% in ${x.measured_in} [${(x.verdict || "").toUpperCase()}]`).join("\n");
    return `[${sym} · Primary Concall vs. Filing Audit]\nManagement Credibility Score: ${pvd.score} (${pvd.credibility_pct ?? 75}%)\n${rowsTxt}\n• Forward FY27 Outlook: ${(r.forward_guidance || []).map((g) => `${g.metric} at ${g.target}`).join(" | ")}`;
  }
  if (/cash|fcf|conversion|cfo|quality/.test(q)) {
    const lastC = c.rows[c.rows.length - 1] || {};
    return `[${sym} · Cash Quality & Conversion Audit]\n• 5-Year Cumulative CFO/PAT Conversion: ${c.conversion_5y}% (${c.conversion_5y >= 85 ? "High quality — accounting profits turn into real cash" : "Watch — working capital absorbing operating cash"}).\n• Latest Year (${lastC.year}): Operating Cash Flow ₹${fmtNum(lastC.cfo)} Cr vs PAT ₹${fmtNum(lastC.pat)} Cr.\n• 6-Year Free Cash Flow (FCF in ₹ Cr): ${c.fcf.map(fmtNum).join(" → ")}.`;
  }
  if (/debt|balance|leverage|working capital|ccc|cycle|receiv|inventory/.test(q)) {
    return `[${sym} · Balance Sheet & Working Capital Audit]\n• Leverage: Debt/Equity is ${L.de}x with borrowings at ₹${fmtNum(b.debt[b.debt.length - 1])} Cr.\n• Cash Conversion Cycle (6Y trend): ${b.ccc.join(" → ")} days.\n• Latest Working Capital Breakdown: Debtor Days ${b.debtor_days ? b.debtor_days[b.debtor_days.length - 1] : "—"}d + Inventory Days ${b.inventory_days ? b.inventory_days[b.inventory_days.length - 1] : "—"}d − Payable Days ${b.payable_days ? b.payable_days[b.payable_days.length - 1] : "—"}d.`;
  }
  if (/margin|opm|ebitda|growth|traject|revenue|profit|cagr/.test(q)) {
    return `[${sym} · Multi-Year Trajectory Audit]\n• Revenue Growth: 5Y CAGR ${t.sales_cagr_5y}% | 3Y CAGR ${t.sales_cagr_3y}% (Latest FY Revenue: ₹${fmtNum(L.sales)} Cr).\n• Profit Growth: 5Y PAT CAGR ${t.pat_cagr_5y}% | 3Y PAT CAGR ${t.pat_cagr_3y}% (Latest FY PAT: ₹${fmtNum(L.pat)} Cr).\n• Margin Trajectory: Operating Margin is ${L.opm}% (${t.opm_change_3y >= 0 ? "+" : ""}${t.opm_change_3y} pts over 3Y).`;
  }
  if (/bull|bear|risk|thesis|buy|sell/.test(q)) {
    return `[${sym} · Primary-Source Bull vs. Bear Thesis]\n▲ BULL CASE:\n${r.bull_bear.bull.map((x) => "  • " + x).join("\n")}\n▼ BEAR CASE:\n${r.bull_bear.bear.map((x) => "  • " + x).join("\n")}`;
  }
  return `[${sym} (${r.name}) · Primary Filing Synthesis]\n• Scale & Multiples: Revenue ₹${fmtNum(L.sales)} Cr (5Y CAGR ${t.sales_cagr_5y}%), PAT ₹${fmtNum(L.pat)} Cr, OPM ${L.opm}%, ROCE ${r.top_ratios["ROCE"] || "—"}, P/E ${r.top_ratios["Stock P/E"] || "—"}.\n• Execution & Cash: ${pvd.score} over last 4 concalls; 5Y CFO/PAT cash conversion at ${c.conversion_5y}%; D/E at ${L.de}x.`;
}

